import socket,selectors,time,ipaddress,math
def serve(listener,upstream,stop,idle=.3,max_sessions=2):
    if listener.family!=socket.AF_INET or listener.getsockopt(socket.SOL_SOCKET,socket.SO_TYPE)!=socket.SOCK_DGRAM:raise ValueError('IPv4 UDP listener required')
    if not ipaddress.ip_address(listener.getsockname()[0]).is_loopback:raise ValueError('loopback listener required')
    if not isinstance(upstream,tuple) or len(upstream)!=2 or not isinstance(upstream[0],str):raise ValueError('upstream tuple required')
    if ipaddress.ip_address(upstream[0]).version!=4 or not ipaddress.ip_address(upstream[0]).is_loopback or type(upstream[1]) is not int or not 1<=upstream[1]<=65535:raise ValueError('loopback upstream required')
    if isinstance(idle,bool) or not isinstance(idle,(int,float)) or not math.isfinite(idle) or not .05<=idle<=5:raise ValueError('idle bound required')
    if type(max_sessions) is not int or not 1<=max_sessions<=8:raise ValueError('session limit required')
    previous=listener.gettimeout();sessions={}
    stats={'created':0,'closed':0,'to_upstream':0,'to_client':0,'dropped_full':0,'dropped_oversize':0}
    def remove(client,selector):
        conn,last=sessions.pop(client)
        selector.unregister(conn);conn.close();stats['closed']+=1
    try:
        listener.setblocking(False)
        with selectors.DefaultSelector() as selector:
            selector.register(listener,selectors.EVENT_READ,None)
            try:
                while not stop.is_set():
                    now=time.monotonic()
                    for client,(conn,last) in list(sessions.items()):
                        if now-last>=idle:remove(client,selector)
                    for key,_ in selector.select(.02):
                        if key.data is None:
                            try:payload,client=listener.recvfrom(8193)
                            except BlockingIOError:continue
                            if len(payload)>8192:stats['dropped_oversize']+=1;continue
                            if client not in sessions:
                                if len(sessions)>=max_sessions:stats['dropped_full']+=1;continue
                                conn=socket.socket(socket.AF_INET,socket.SOCK_DGRAM)
                                try:
                                    conn.bind(('127.0.0.1',0));conn.connect(upstream);conn.setblocking(False)
                                    selector.register(conn,selectors.EVENT_READ,client)
                                except BaseException:conn.close();raise
                                sessions[client]=(conn,now);stats['created']+=1
                            conn,_=sessions[client];conn.send(payload)
                            sessions[client]=(conn,time.monotonic());stats['to_upstream']+=1
                        else:
                            client=key.data
                            try:payload=key.fileobj.recv(65507)
                            except BlockingIOError:continue
                            listener.sendto(payload,client)
                            sessions[client]=(key.fileobj,time.monotonic());stats['to_client']+=1
            finally:
                for client in list(sessions):remove(client,selector)
    finally:listener.settimeout(previous)
    return stats
```

每个会话的本地上游socket提供独立源端口，selector携带客户端身份用于反向分流；空闲清理避免无限占用端口。UDP仍可丢包，本练习不提供可靠传输保证，也不宣称它与内核NAT功能完全相同。

原理补充：
NAT 在经过网关时转换地址，PAT 还转换端口，常用于地址复用或地址边界映射。状态型转换维护双向映射，故障可能来自端口耗尽、状态表或回程不一致。NAT 不是加密，也不能代替明确的访问控制策略。

