import pathlib,sys,socket,threading,time,os,json
sys.path.insert(0,str(pathlib.Path.cwd()));import task
baseline=len(os.listdir('/proc/self/fd'))
origin=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);origin.bind(('127.0.0.1',0));origin.settimeout(.03)
listener=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);listener.bind(('127.0.0.1',0));listener.settimeout(.9)
clients=[];threads=[];stop=threading.Event();origin_stop=threading.Event();seen=[];errors=[];results=[]
def backend():
    waiting=[]
    try:
        while not origin_stop.is_set():
            try:data,addr=origin.recvfrom(65507)
            except socket.timeout:continue
            seen.append((data,addr))
            if len(seen)<=2:
                waiting.append((data,addr))
                if len(waiting)==2:
                    for payload,peer in reversed(waiting):origin.sendto(b'answer:'+payload,peer)
            else:origin.sendto(b'answer:'+data,addr)
    except BaseException as e:
        if not origin_stop.is_set():errors.append(e)
def run():
    try:results.append(task.serve(listener,origin.getsockname(),stop,idle=.3,max_sessions=2))
    except BaseException as e:errors.append(e)
try:
    for target in [backend,run]:
        t=threading.Thread(target=target);threads.append(t);t.start()
    for _ in range(3):
        c=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);c.bind(('127.0.0.1',0));c.settimeout(.15);clients.append(c)
    a,b,c=clients
    a.sendto(b'A0',listener.getsockname());b.sendto(b'B0',listener.getsockname())
    assert a.recv(65507)==b'answer:A0';assert b.recv(65507)==b'answer:B0','reordered responses went to wrong client'
    amap=next(addr for data,addr in seen if data==b'A0');bmap=next(addr for data,addr in seen if data==b'B0')
    assert amap!=bmap and amap not in [a.getsockname(),b.getsockname()] and bmap not in [a.getsockname(),b.getsockname()]
    a.sendto(b'',listener.getsockname());assert a.recv(65507)==b'answer:','zero-length UDP datagram lost'
    assert seen[-1][1]==amap,'same live client mapping changed'
    payload=bytes(range(256))*32
    b.sendto(payload,listener.getsockname());assert b.recv(65507)==b'answer:'+payload
    assert seen[-1][1]==bmap
    # A third source socket cannot inject a reply into the connected upstream socket.
    c.sendto(b'spoof',amap);a.settimeout(.04)
    try:a.recv(65507)
    except socket.timeout:pass
    else:raise AssertionError('untrusted origin reply delivered')
    before=len(seen);c.sendto(b'C-blocked',listener.getsockname());c.settimeout(.04)
    try:c.recv(65507)
    except socket.timeout:pass
    else:raise AssertionError('session capacity ignored')
    assert len(seen)==before
    a.sendto(b'x'*8193,listener.getsockname());time.sleep(.04);assert len(seen)==before,'oversize datagram forwarded or truncated'
    time.sleep(.38)
    c.settimeout(.2);c.sendto(b'C-new',listener.getsockname());assert c.recv(65507)==b'answer:C-new','expired slots were not reusable'
    stop.set();threads[1].join(1);assert not threads[1].is_alive()
    assert listener.fileno()>=0 and listener.gettimeout()==.9,'caller listener closed or mode changed'
    assert not errors,errors
    assert results==[{'created':3,'closed':3,'to_upstream':5,'to_client':5,'dropped_full':1,'dropped_oversize':1}],results
    pathlib.Path('session-results.json').write_text(json.dumps(results[0]))
